from lib import *
chapter(7,'maths','parallel-and-intersecting-lines','Parallel and Intersecting Lines',
 ('Railway tracks','Railway tracks never meet however far they go. A road crossing them cuts across. In this chapter we study lines that never meet and lines that cross, and the angles they make.'),
 [('Angles made by lines',['Two lines that meet at a point are intersecting lines. They make four angles.','Angles opposite each other at the crossing are called vertically opposite angles and they are always equal.','Two angles next to each other on a straight line add up to 180 degrees. They are a linear pair.']),
  ('Parallel lines and a transversal',['Parallel lines are always the same distance apart and never meet.','A line that cuts two or more lines is called a transversal.','When a transversal cuts two parallel lines, corresponding angles are equal, alternate interior angles are equal and the interior angles on the same side add up to 180 degrees.']),
  ('Perpendicular lines and drawing',['Two lines that meet at 90 degrees are perpendicular.','To draw a line parallel to a given line, use a set square sliding along a ruler, or copy a corresponding angle.'])],
 [('Two lines cross and one angle is 70 degrees. Find the other three.',[('The angle opposite is also 70 degrees.','Vertically opposite.'),('Each neighbour is 180 minus 70, which is 110 degrees.','Linear pair.')])],
 ('Explain how you know two lines are parallel using a transversal.',['Corresponding angles are equal.','Or interior angles on the same side add to 180.'],['Confusing vertically opposite angles with a linear pair.']),
 ['Vertically opposite angles are equal.','A linear pair adds to 180 degrees.','A transversal with parallel lines gives equal corresponding and alternate angles.'],
 [mcq('1',1,'Vertically opposite angles are','equal',[('supplementary','A linear pair is supplementary, not opposite angles.'),('always 90','They can be any size.')],'They are formed by the same two lines.'),
  num('2',1,'A linear pair has one angle 70. What is the other?',110,'180 minus 70.',[(20,'That is 90 minus 70.')],'degrees'),
  tf('3',1,'Parallel lines meet if extended far enough.',False,'They stay the same distance apart.'),
  mcq('4',1,'A line cutting two lines is a','transversal',[('ray','A ray starts at a point.'),('segment','A segment has ends.')],'It cuts across both.'),
  num('5',2,'Two parallel lines are cut by a transversal. A corresponding angle is 65. The other is',65,'Corresponding angles are equal.',[(115,'That is the linear partner.')],'degrees'),
  num('6',2,'Interior angles on the same side add to',180,'For parallel lines.',[(90,'That is perpendicular.')],'degrees'),
  mcq('7',2,'Two lines at 90 degrees are','perpendicular',[('parallel','Parallel lines never meet.'),('transversal','A transversal is a cutting line.')],'A right angle between them.'),
  num('8',3,'Two lines cross. One angle is 40. Its vertically opposite angle is',40,'Equal.',[(140,'That is its neighbour.')],'degrees')],
 keep=['transversal','parallel','perpendicular'])
chapter(7,'maths','number-play','Number Play',
 ('The magic of numbers','Take any three digit number and write it twice to make a six digit number. Divide by 7, then 11, then 13. You get your first number back! Number play is full of surprises.'),
 [('Patterns and puzzles',['Numbers hide patterns and puzzles that are fun to explore.','A number sequence follows a rule. Spotting the rule lets us find the next terms.']),
  ('Divisibility rules',['A number is divisible by 2 if it ends in an even digit, by 5 if it ends in 0 or 5 and by 10 if it ends in 0.','Divisible by 3 if the digit sum is divisible by 3 and by 9 if the digit sum is divisible by 9.','Divisible by 11 if the difference between the sum of digits in odd places and the sum in even places is 0 or a multiple of 11.']),
  ('Sequences and Collatz',['In the Collatz sequence, halve an even number and make an odd number three times itself plus one.','It always seems to reach 1, but nobody has proved it for all numbers.']),
  ('Parity and squares in grids',['Parity means whether a number is even or odd. Even plus even is even, odd plus odd is even and odd plus even is odd.','Parity can solve puzzles, such as why a chessboard with two opposite corners removed cannot be covered fully by dominoes.'])],
 [('Is 2,376 divisible by 9?',[('Add the digits: 2 plus 3 plus 7 plus 6 is 18.','Digit sum.'),('18 is divisible by 9, so 2,376 is.','Rule of 9.')])],
 ('Explain why the sum of two odd numbers is always even.',['Odd numbers are one more than an even number.','Two ones make another pair.'],['Thinking odd plus odd is odd.']),
 ['Divisibility rules save time.','Parity is odd or even.','Collatz is an open problem.'],
 [mcq('1',1,'A number is divisible by 9 if its digit sum is','divisible by 9',[('even','Evenness is a rule for 2.'),('prime','Not related.')],'Add the digits.'),
  mcq('2',1,'Odd + odd is','even',[('odd','2 odd numbers pair up.'),('prime','Not always.')],'Example 3 plus 5 equals 8.'),
  tf('3',1,'4,320 is divisible by 5.',True,'It ends in 0.'),
  num('4',1,'Digit sum of 2,376',18,'2 plus 3 plus 7 plus 6.',[(16,'Recount the digits.')]),
  mcq('5',2,'Which is divisible by 3?','4,512',[('4,513','Digit sum 13 is not a multiple of 3.'),('4,514','Digit sum 14 is not.')],'Digit sum 12.'),
  mcq('6',2,'Even x odd is','even',[('odd','Any multiple of 2 is even.'),('prime','Not always.')],'2 times anything is even.'),
  tf('7',2,'1,331 is divisible by 11.',True,'Odd place sum 1+3=4, even place sum 3+1=4, difference 0.'),
  num('8',3,'Next Collatz number after 5',16,'5 is odd: 3 times 5 plus 1.',[(2,'That is half of 5, which is wrong for odd numbers.')])],
 keep=['divisibility','parity','Collatz'])
chapter(7,'maths','a-tale-of-three-intersecting-lines','A Tale of Three Intersecting Lines',
 ('The triangle','Three lines that cross each other make a triangle. Triangles are the strongest shape and are used in bridges and roofs. We explore their angles and sides.'),
 [('Angle sum of a triangle',['The three angles of every triangle add up to 180 degrees.','Tear the corners and place them side by side. They form a straight line.','So if two angles are known, the third is 180 minus their sum.']),
  ('Types of triangles',['By sides: equilateral has all sides equal, isosceles has two equal sides and scalene has no equal sides.','By angles: acute has all angles less than 90, right has one angle of 90 and obtuse has one angle more than 90.']),
  ('Exterior angle',['If a side of a triangle is extended, the angle outside is an exterior angle.','An exterior angle equals the sum of the two interior opposite angles.']),
  ('Constructing triangles and the triangle inequality',['The sum of any two sides of a triangle is greater than the third side. Sides 2, 3 and 7 cannot form a triangle.','We can construct a triangle with a ruler, compass and protractor if we know enough measurements.'])],
 [('Two angles of a triangle are 50 and 60. Find the third.',[('Sum is 110.','Add.'),('180 minus 110 is 70 degrees.','Use the angle sum.')])],
 ('Explain why a triangle cannot have two right angles.',['That would use 180 degrees.','Nothing would remain for the third angle.'],['Forgetting the triangle inequality.']),
 ['Angles add to 180.','Types: equilateral, isosceles, scalene; acute, right, obtuse.','Exterior angle = sum of two opposite interior angles.','Two sides must exceed the third.'],
 [num('1',1,'Angles of a triangle add to',180,'This is true for every triangle.',[(360,'That is for a quadrilateral.')],'degrees'),
  num('2',1,'Two angles are 50 and 60. The third is',70,'180 minus 110.',[(110,'That is the sum of two.')],'degrees'),
  mcq('3',1,'A triangle with all sides equal is','equilateral',[('isosceles','Only two sides are equal.'),('scalene','No sides equal.')],'Equal sides.'),
  tf('4',1,'A triangle can have two right angles.',False,'They would use up 180.'),
  num('5',2,'Exterior angle where interior opposite angles are 40 and 55',95,'Add the two.',[(85,'That is the third interior angle.')],'degrees'),
  mcq('6',2,'Which sides can form a triangle?','3, 4, 5',[('2, 3, 7','2 plus 3 is not more than 7.'),('1, 1, 3','1 plus 1 is not more than 3.')],'Sum of two exceeds third.'),
  mcq('7',2,'A triangle with angles 90, 45, 45 is','right and isosceles',[('equilateral','Angles would be 60.'),('obtuse','No angle over 90.')],'It has a right angle and two equal angles.'),
  num('8',3,'In an isosceles triangle the top angle is 40. Each base angle is',70,'(180 minus 40) divided by 2.',[(140,'That is the sum of both base angles.')],'degrees')],
 keep=['triangle','angle sum','exterior angle'])
